import json, collections
L=[]
def a(p,s,l,k,sev,c,f): L.append(dict(passage=p,source=s,lost=l,kind=k,severity=sev,category=c,fix=f))
G,W,S="GRAMMAR","WORKAROUND","STYLE"
# D03
a("D03","A HARE one day ridiculed ...","The story is fiction, but every sentence must take an opener that claims a source of knowledge (GIVEN), so narrated or imagined status is not marked.",G,2,"speech act / text status","Add an opener TOLD for narrated or fictional content.")
a("D03","A HARE ... the Tortoise","The difference between a newly introduced participant and one treated as already known is not marked; only the presence of NAMED hints at first mention.",G,1,"definiteness","Add a phrase-initial particle KNOWN (already identifiable) contrasting with unmarked new.")
a("D03","the short feet and slow pace","Two things joined as one object cannot be said in one phrase; the sentence must be repeated once per item.",W,2,"coordination","Add a phrase joiner AND between phrases under one role.")
a("D03","who replied, laughing: \"...\"","Inside a quoted block it is not defined that ME and YOU mean the quoted speaker and hearer rather than the writer and reader.",G,3,"reported speech","Add a QUOTE block form whose ME/YOU are bound to the AGENT and TO of the speech predicate; plain blocks keep the writer's ME/YOU.")
a("D03","I will beat you in a race","A block has no opener, so the quoted sentence's own force (a boast and challenge, a commitment) is reduced to a bare future statement.",G,2,"speech act","Allow an optional opener as the first element of a QUOTE block.")
a("D03","Though you be swift as the wind","Concession ('even if') inside an embedded clause is impossible because CONCEDE only links whole sentences; it decodes as a plain condition.",G,2,"concession","Allow relation particles inside IF: IF CONCEDE {..} {..} = even if.")
a("D03","swift as the wind","Equal-degree comparison has no construct; THAN only gives 'more than'.",W,2,"comparison","Add role AS (standard of equal degree) beside THAN.")
a("D03","simply impossible","The intensifier on the believed content is lost; EMPHASIS is the writer's sentence-level attitude and cannot sit inside the belief.",G,1,"degree","Add a degree slot before a predicate or modifier: VERY, SLIGHT, FULL.")
a("D03","they agreed / the two started together","There is no way to refer to two named things jointly; a pair had to be defined in its own sentence.",W,2,"coordination","Phrase joiner AND, with NAMED allowed on the joined phrase (H AND T NAMED P).")
a("D03","that the Fox should choose the course","The arranged, obligation-like sense of 'should' inside the agreement is reduced to a plain future.",G,2,"modality","Add a modal slot after aspect: MUST, MAY, CAN, SHOULD.")
a("D03","had reached the goal / should choose","Whether PAST or FUTURE inside a block is counted from the main clause's time or from the writing time is not defined.",G,2,"relative time","State in the spec that time in a block is relative to the enclosing clause.")
a("D03","went on","Continuing an activity already under way is only approximated by ONGOING, which says in progress but not 'kept on'.",W,1,"aspect / phase","Add phase particles to the aspect slot: BEGIN, CONTINUE, STOP.")
a("D03","a slow but steady pace / Slow but steady","Contrast between two modifiers of one head cannot be marked; they decode as 'slow and steady', losing the point of the moral.",G,2,"contrast inside phrase","Allow CONTRAST as a linker between modifiers: pace KIND slow CONTRAST steady.")
a("D03","fell fast asleep","Entering a state has no aspect marker; it needs a 'begin' predicate over a block.",W,1,"aspect / phase","BEGIN in the aspect slot.")
a("D03","At last waking up","That the event came after a long wait, later than expected, is lost.",G,2,"expectation / phase","Add focus or aspect particles LATE (finally) and EARLY (already).")
a("D03","as fast as he could","Highest degree within ability needs a clumsy 'greatest speed that he is able' clause; there is no superlative and no ability marker.",W,2,"degree / superlative","Add degree particle MOST and modal CAN.")
a("D03","dozing after her fatigue","WHEN gives a time but not before or after; I replaced 'after' with CAUSE, which changes the claim.",G,2,"time relation","Add roles BEFORE and AFTER (or split WHEN into three).")
a("D03","Slow but steady wins the race","A statement about a kind in general and one about a particular individual and race look the same.",G,2,"genericity","Add a quantifier ANY (generic or free choice) before the head.")
a("D03","her assertion / he could","The sex of the two characters is not carried once they are handles.",S,1,"gender","none: out of scope")
a("D03","On the day appointed for the race the two started","Role order is free and meaningless, so what a sentence is set against or about (fronted time, topic) cannot be shown.",G,1,"topic","Add a focus-slot particle TOPIC before the phrase the sentence is about.")
# D07
a("D07","One skilled in circumvention of the law","The whole entry is ironic, but DEFINE presents it as a sincere definition; a reader of the decoded text takes it literally.",G,3,"tone / irony","Add attitude IRONY (writer does not mean it straight) or JEST.")
a("D07","skilled in circumvention","The field in which a property holds has no role; FOR or AT must be bent to fit.",W,1,"respect / domain","Add role ABOUT (topic, field, respect).")
a("D07","when you wish him to listen","Generic 'you' meaning anyone becomes YOU, the actual addressee.",G,2,"impersonal reference","Add head ONE (any person, generic) beside ME and YOU.")
a("D07","A person who talks when you wish him to listen","SELF in a clause nested inside a modifying clause does not say which head it stands for.",G,2,"reference in nested clauses","Let NAMED be written directly after the head (person NAMED P KIND {...P...}) and say SELF always means the nearest head.")
a("D07","those that are not good to eat, as well as those that are","The 'B as well as A' framing, which presents the inedible ones as the surprising main case, is flattened to two additive sentences.",W,1,"coordination","Phrase joiner AND plus existing ALSO on the surprising member.")
