real=len(L)
cnt=collections.Counter(x['kind'] for x in L); cat=collections.Counter(x['category'].split(' / ')[0] for x in L)
print(real,cnt,cat.most_common(12))
L.append(dict(passage="ALL",summary="The largest single gap is joining: with no AND for phrases, predicates or clauses, and OR only between whole blocks, almost every source sentence had to be split or have material repeated, and definitions with two halves fell out of their DEFINE. Second is everything inside a block: strength, attitude, relations (though, but) and speech-act force exist only at sentence level, so reported speech, embedded possibility and concession are all flattened, and ME/YOU and time inside a block are undefined. Third, there are no deontic or ability modals, no degree or approximation words, no before/after, and no phase words (still, again, finally, begin, continue), which hurt the standard, the bank statement and the chat most. Dialogue cannot mark who speaks, and tone (irony, annoyance, joking) has no slot, so the satire decodes as sincere. Used most: GIVEN, the roles AGENT/THEME/WITH/WHEN, KIND and KIND-clauses with SELF, NAMED handles, CONTRAST/ADD/SEQUENCE, DONE/ONGOING, and DEFINE. Used least or never: RECALLED, ASSUMED, CERTAIN, LIKELY, REGRET, INSTEAD, ONLY, WHAT, and the whole logic layer (EACH, WHILE, RETURN, numbered slots)."))
json.dump(L,open('<workdir>/run1/loss_C.json','w'),ensure_ascii=False,indent=1)
